    "type": "api_call",
    "ai_instructions": {
      "user_message": "请输入身份证号查询社保",
      "action": "查询社保"
    },
    "api": {
      "id": "api_social_security_query",
      "path": "/api/gov/social-security",
      "method": "GET",
      "request": [
        {
          "name": "id_card",
          "type": "string",
          "label": "身份证号",
          "required": true
        }
      ],
      "response": [
        {
          "name": "records",
          "type": "array",
          "desc": "社保记录"
        },
        {
          "name": "total_months",
          "type": "integer",
          "desc": "累计缴纳月数"
        },
        {
          "name": "balance",
          "type": "float",
          "desc": "账户余额"
        }
      ]
    }
  }
}

